export function normalizePath(pathname: string) {
  let value = pathname || '/';
  try { value = decodeURI(value); } catch {}
  if (value.length > 1) value = value.replace(/\/+$/, '');
  return value || '/';
}

export function getArticleByPath(pathname: string) {
  const path = normalizePath(pathname);
  return GUIDE_ARTICLES.find((item) => normalizePath(item.path) === path);
}

export function getDomainArticles(domainKey: string) {
  return GUIDE_ARTICLES.filter((item) => item.domainKey === domainKey).sort((a,b)=>a.guideOrder-b.guideOrder);
}

export function getNeighbors(pathname: string) {
  const current = getArticleByPath(pathname);
  if (!current) return { current: undefined, prev: undefined, next: undefined };
  const list = getDomainArticles(current.domainKey);
  const i = list.findIndex((x)=>x.translationKey===current.translationKey);
  return { current, prev: i>0?list[i-1]:undefined, next:i>=0&&i<list.length-1?list[i+1]:undefined };
}

export function getRelated(pathname: string, limit=3) {
  const current = getArticleByPath(pathname);
  if (!current) return [];
  const list = getDomainArticles(current.domainKey);
  const sameStage = list.filter((x)=>x.stageKey===current.stageKey && x.translationKey!==current.translationKey);
  const nearby = list.filter((x)=>x.translationKey!==current.translationKey);
  return [...sameStage, ...nearby].filter((x,i,a)=>a.findIndex(y=>y.translationKey===x.translationKey)===i).slice(0,limit);
}
